// Номер пина, к которому подключён светодиод
int ledPin = 13;

void setup() {
  // Настраиваем этот пин как выход
  pinMode(ledPin, OUTPUT);
}

void loop() {
  // Включаем светодиод (подаём высокий уровень на пин)
  digitalWrite(ledPin, HIGH);
  // Ждём 1 секунду (1000 миллисекунд)
  delay(1000);

  // Выключаем светодиод (снимаем напряжение с пина)
  digitalWrite(ledPin, LOW);
  // Снова ждём 1 секунду
  delay(1000);
}
